 }

 function parseOptions(args: string[]): CliOptions {
@@ -20,6 +22,9 @@ function parseOptions(args: string[]): CliOptions {
     if ((option === '--content' || option === '--output' || option === '--templates') && (!value || value.startsWith('--'))) {
       throw new Error(`${option} requires a directory`);
     }
+    if (option === '--port' && (!value || value.startsWith('--'))) {
+      throw new Error('--port requires a value');
+    }
     if (option === '--content') {
       options.contentDir = value;
       index += 1;
@@ -29,6 +34,13 @@ function parseOptions(args: string[]): CliOptions {
     } else if (option === '--templates') {
       options.templatesDir = value;
       index += 1;
+    } else if (option === '--port') {
+      const port = Number(value);
+      if (!Number.isInteger(port) || port < 0 || port > 65535) {
+        throw new Error('--port must be an integer between 0 and 65535');
+      }
+      options.port = port;
+      index += 1;
